#include <array>
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <numeric>
#include <random>
#include <vector>
using namespace std;
constexpr int N=26,K=63,W=17;
using Bits=array<uint64_t,W>;
struct Gate { int a,b,op; };
mt19937_64 rng(132);
vector<uint32_t> pos,neg;
Bits target,positive,hardmask,pairmask;vector<vector<Gate>> seedbank;array<Bits,8> costplanes;vector<int> costs;bool positivePriority=true;
vector<Bits> inputs;
int ones(const Bits&a){int n=0;for(auto x:a)n+=__builtin_popcountll(x);return n;}
Bits fun(const Bits&a,const Bits&b,int op){Bits z;for(int i=0;i<W;i++)z[i]=op?(a[i]|b[i]):(a[i]&b[i]);return z;}
vector<Bits> eval(const vector<Gate>&g){auto w=inputs;for(auto x:g)w.push_back(fun(w[x.a],w[x.b],x.op));return w;}
void resetCosts(){costs.assign(pos.size()+neg.size(),1);for(auto &p:costplanes)p.fill(0);for(int i=0;i<(int)costs.size();i++)costplanes[0][i/64]|=1ull<<(i%64);}
void punish(const Bits&v){for(int i=0;i<(int)costs.size();i++)if((v[i/64]^target[i/64])>>(i%64)&1)costs[i]=min(255,costs[i]+1);for(auto &p:costplanes)p.fill(0);for(int i=0;i<(int)costs.size();i++)for(int q=0;q<8;q++)if(costs[i]>>q&1)costplanes[q][i/64]|=1ull<<(i%64);}
int rawscore(const Bits&x){int s=0;for(int i=0;i<W;i++)s+=__builtin_popcountll(x[i]^target[i]);return s;}
int64_t score(const Bits&x,int weight=1){int64_t s=0;for(int i=0;i<W;i++){uint64_t e=x[i]^target[i];for(int q=0;q<8;q++)s+=(1<<q)*__builtin_popcountll(e&costplanes[q][i]);if(positivePriority)s+=(1ll<<30)*__builtin_popcountll(e&hardmask[i]);s+=(1ll<<20)*__builtin_popcountll(e&pairmask[i]);}return s;}
int64_t maskedscore(const Bits&a,const Bits&b,int op,const Bits&mask,const Bits&need,int weight){int64_t s=0;for(int i=0;i<W;i++){uint64_t e=((op?(a[i]|b[i]):(a[i]&b[i]))^need[i])&mask[i];if(e)for(int q=0;q<8;q++)s+=(1<<q)*__builtin_popcountll(e&costplanes[q][i]);if(positivePriority)s+=(1ll<<30)*__builtin_popcountll(e&hardmask[i]);s+=(1ll<<20)*__builtin_popcountll(e&pairmask[i]);}return s;}
int properDirty(const vector<Gate>&g){auto sig=eval(g);array<bool,N+K>active={};vector<int>todo={N+K-1};while(!todo.empty()){int a=todo.back();todo.pop_back();if(active[a])continue;active[a]=true;if(a>=N){todo.push_back(g[a-N].a);todo.push_back(g[a-N].b);}}array<bool,K>bad={};for(int a=0;a<N;a++)for(int b=a;b<N;b++){bool edge=a<13&&b>=13&&((a+b-13)%13==0||(a+b-13)%13==1||(a+b-13)%13==3||(a+b-13)%13==9);if(edge)continue;array<bool,N+K>v={};v[a]=v[b]=true;for(int j=0;j<K;j++){v[N+j]=g[j].op?(v[g[j].a]||v[g[j].b]):(v[g[j].a]&&v[g[j].b]);if(active[N+j]&&!g[j].op&&v[N+j])bad[j]=true;}}for(int j=0;j<K;j++)if(bad[j])for(int a=0;a<N+j;a++)if(sig[N+j]==sig[a]){bad[j]=false;break;}return count(bad.begin(),bad.end(),true);}
vector<Gate> seed(){const auto&g=seedbank[rng()%seedbank.size()];int count=g.size();vector<Gate> out;vector<int> id(N+count);iota(id.begin(),id.begin()+N,0);for(int i=0;i<count;i++){int left=K-count-(int(out.size())-i);int add=(i==count-1)?left:min(left,int(rng()%3));for(int q=0;q<add;q++)out.push_back({int(rng()%(N+out.size())),int(rng()%(N+out.size())),int(rng()%2)});out.push_back({id[g[i].a],id[g[i].b],g[i].op});id[N+i]=N+out.size()-1;}return out;}
void reorder(vector<Gate>&g){
 vector<Gate> out;vector<int> id(N+K,-1);for(int i=0;i<N;i++)id[i]=i;vector<int> todo(K);iota(todo.begin(),todo.end(),0);
 while(!todo.empty()){vector<int> ready;for(int k:todo)if(id[g[k].a]>=0 && id[g[k].b]>=0 && (k<K-1 || todo.size()==1))ready.push_back(k);if(ready.empty()){cerr<<"topo failure"<<endl;exit(2);}int k=ready[rng()%ready.size()];out.push_back({id[g[k].a],id[g[k].b],g[k].op});id[N+k]=N+out.size()-1;todo.erase(find(todo.begin(),todo.end(),k));}g=out;
}
void save(const vector<Gate>&g,string f){ofstream o(f);o<<"[";for(int i=0;i<K;i++){if(i)o<<",";o<<"["<<g[i].op<<","<<g[i].a<<","<<g[i].b<<"]";}o<<"]\n";}
int main(int argc,char**argv){if(argc<6){cerr<<"missing arguments"<<endl;return 2;}double seconds=argc>1?stod(argv[1]):600;string base=argc>2?argv[2]:".";int weight=argc>3?stoi(argv[3]):4;if(argc>4)rng.seed(stoull(argv[4]));uint32_t all=(1<<13)-1;int adj[13]={};for(int p=0;p<13;p++)for(int l=0;l<13;l++)if((p+l)%13==0||(p+l)%13==1||(p+l)%13==3||(p+l)%13==9){adj[p]|=1<<l;pos.push_back((1<<p)|(1<<(13+l)));}for(int s=0;s<(1<<13);s++){int cover=0;for(int p=0;p<13;p++)if(s>>p&1)cover|=adj[p];int t=all^cover,closure=0;for(int p=0;p<13;p++)if(!(adj[p]&t))closure|=1<<p;if(s==closure)neg.push_back(s|(t<<13));}int singletonStart=pos.size()+neg.size();for(int i=0;i<N;i++)neg.push_back(1u<<i);int pairStart=pos.size()+neg.size();for(int a=0;a<N;a++)for(int b=a+1;b<N;b++){bool edge=a<13&&b>=13&&((a+b-13)%13==0||(a+b-13)%13==1||(a+b-13)%13==3||(a+b-13)%13==9);if(!edge)neg.push_back((1u<<a)|(1u<<b));}vector<uint32_t> tests=pos;tests.insert(tests.end(),neg.begin(),neg.end());inputs.resize(N);for(int i=0;i<(int)tests.size();i++){if(i<(int)pos.size()){target[i/64]|=1ull<<(i%64);positive[i/64]|=1ull<<(i%64);}for(int p=0;p<N;p++)if(tests[i]>>p&1)inputs[p][i/64]|=1ull<<(i%64);}
for(int q=0;q<W;q++)hardmask[q]=positive[q];for(int i=singletonStart;i<pairStart;i++)hardmask[i/64]|=1ull<<(i%64);for(int i=pairStart;i<(int)tests.size();i++)pairmask[i/64]|=1ull<<(i%64);ifstream sf(argv[5]);int count=0;sf>>count;if(!sf||count<1){cerr<<"invalid seed bank"<<endl;return 2;}for(int z=0;z<count;z++){int m=0;if(!(sf>>m)||m<1||m>K){cerr<<"invalid seed size"<<endl;return 2;}vector<Gate> g(m);for(int j=0;j<m;j++){sf>>g[j].op>>g[j].a>>g[j].b;if(!sf||g[j].op<0||g[j].op>1||g[j].a<0||g[j].a>=N+j||g[j].b<0||g[j].b>=N+j){cerr<<"invalid seed gate"<<endl;return 2;}}seedbank.push_back(g);}
 auto start=chrono::steady_clock::now();int total=0,restarts=0,best=1000,bestDirty=1000,bestSuper=1000,bestPairs=1000,bestQuadratic=1000;bool recordedQuadratic=false;vector<int> errorSeen(pos.size()+neg.size());
 while(chrono::duration<double>(chrono::steady_clock::now()-start).count()<seconds){auto g=seed();reorder(g);auto vals=eval(g);resetCosts();positivePriority=true;
 for(int iter=0;iter<30000;iter++){total++;int j=rng()%K;auto low=vals,high=vals;low[N+j].fill(0);high[N+j].fill(~0ull);for(int k=j+1;k<K;k++){low[N+k]=fun(low[g[k].a],low[g[k].b],g[k].op);high[N+k]=fun(high[g[k].a],high[g[k].b],g[k].op);}Bits mask;for(int q=0;q<W;q++)mask[q]=low.back()[q]^high.back()[q];int64_t oldlocal=maskedscore(vals[g[j].a],vals[g[j].b],g[j].op,mask,target,1);int64_t bestlocal=oldlocal;Gate cand=g[j];int equals=1;
 for(int a=0;a<N+j;a++)for(int b=a;b<N+j;b++)for(int op=0;op<2;op++){int64_t v=maskedscore(vals[a],vals[b],op,mask,target,1);if(v<bestlocal){bestlocal=v;cand={a,b,op};equals=1;}else if(v==bestlocal&&rng()%++equals==0)cand={a,b,op};}g[j]=cand;vals=eval(g);int raw=rawscore(vals.back());bool badhard=false;for(int q=0;q<W;q++)badhard|=((vals.back()[q]^target[q])&hardmask[q])!=0;if(badhard){cerr<<"hard invariant failed"<<endl;return 2;}if(raw<best){best=raw;cout<<"best raw="<<best<<" iter="<<total<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;save(g,base+"/best.json");}if(raw==0){save(g,base+"/solution.json");return 0;}int pairerrors=0;for(int q=0;q<W;q++)pairerrors+=__builtin_popcountll((vals.back()[q]^target[q])&pairmask[q]);if(pairerrors<bestPairs){bestPairs=pairerrors;cout<<"best pairerrors="<<pairerrors<<" totalerrors="<<raw<<" iter="<<total<<endl;save(g,base+"/best-pairs.json");}if(pairerrors==0){if(raw<bestQuadratic){bestQuadratic=raw;save(g,base+"/best-quadratic.json");cout<<"quadratic exact highererrors="<<raw<<" iter="<<total<<endl;}if(!recordedQuadratic){recordedQuadratic=true;save(g,base+"/first-quadratic.json");ofstream hf(base+"/first-quadratic-higher-failures.json");hf<<"[";bool first=true;for(int i=0;i<singletonStart;i++)if((vals.back()[i/64]^target[i/64])>>(i%64)&1){if(!first)hf<<",";first=false;hf<<"["<<i<<","<<tests[i]<<"]";}hf<<"]\n";}}
 if(iter%100==99){punish(vals.back());for(int i=0;i<(int)errorSeen.size();i++)if((vals.back()[i/64]^target[i/64])>>(i%64)&1)errorSeen[i]++;}
 if(iter%1000==999){int dc=properDirty(g);int fn=__builtin_popcountll((vals.back()[0]^target[0])&positive[0]);if(fn==0&&raw<bestSuper){bestSuper=raw;cout<<"superset falsepositives="<<raw<<" dirty="<<dc<<" iter="<<total<<endl;save(g,base+"/best-super.json");}if(dc&&raw<bestDirty){bestDirty=raw;cout<<"proper dirty candidate raw="<<raw<<" count="<<dc<<" iter="<<total<<endl;save(g,base+"/best-dirty.json");}reorder(g);vals=eval(g);}
 if(iter%1500==1499 && iter+1<30000){auto oldg=g;auto oldvals=vals;for(int z=0;z<2;z++){int k=rng()%K;if(rng()%2)g[k].a=rng()%(N+k);else g[k].b=rng()%(N+k);}vals=eval(g);bool badhard=false;for(int q=0;q<W;q++)badhard|=((vals.back()[q]^target[q])&hardmask[q])!=0;if(badhard){g=oldg;vals=oldvals;}}
 if(iter%30==0&&chrono::duration<double>(chrono::steady_clock::now()-start).count()>=seconds)break;
 }if(rawscore(vals.back())==0){save(g,base+"/solution.json");return 0;}restarts++;cout<<"restart="<<restarts<<" iterations="<<total<<" positivePriority="<<positivePriority<<" weighted="<<score(vals.back())<<" raw="<<rawscore(vals.back())<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;}
 int ep=0,en=0;for(int i=0;i<(int)errorSeen.size();i++)if(errorSeen[i]){if(i<(int)pos.size())ep++;else en++;}cout<<"done best="<<best<<" bestProperDirty="<<bestDirty<<" sampledPositiveErrors="<<ep<<" sampledNegativeErrors="<<en<<" iterations="<<total<<endl;ofstream counts(base+"/error-counts.json");counts<<"[";for(int i=0;i<(int)errorSeen.size();i++){if(i)counts<<",";counts<<errorSeen[i];}counts<<"]\n";
}
